package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	max := 0
	first := true
	for _, f := range strings.Fields(sc.Text()) {
		n, err := strconv.Atoi(f)
		if err != nil {
			continue
		}
		if first || n > max {
			max = n
			first = false
		}
	}
	fmt.Printf("max=%d\n", max)
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	c := 0
	for _, w := range strings.Split(sc.Text(), ",") {
		if strings.TrimSpace(w) != "" {
			c++
		}
	}
	fmt.Printf("words=%d\n", c)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	buf := make([]byte, 64*1024)
	lines, chars := 0, 0
	for {
		n, err := r.Read(buf)
		for i := 0; i < n; i++ {
			chars++
			if buf[i] == '\n' {
				lines++
			}
		}
		if err != nil {
			break
		}
	}
	fmt.Printf("lines=%d chars=%d\n", lines, chars)
}

